-- Repeatable migration: seed data for local development.
--
-- Generated from database/seed/generate_seed.py against Logan PL.xlsx.
-- Re-run that script after editing the spreadsheet to refresh this file.
--
-- Idempotency model:
--   Every row uses a deterministic UUID derived from md5() of a stable key,
--   and every insert ends in `on conflict (id) do nothing`. Re-running this
--   migration on a populated DB is a no-op; missing rows are filled in.
--   For a destructive refresh (e.g. after restructuring the spreadsheet),
--   wipe the data volume with `docker compose down -v` so Flyway's
--   `clean migrate` reapplies everything from scratch.
--
-- Flyway wraps each migration in its own transaction; no explicit begin/commit needed.

set search_path to fitlytics, public;

-- 1. Owner user
--
-- Synthetic dev owner. users.ResolveOrProvision upserts on workos_user_id, so
-- this row is the local mirror the seeded program hangs off. The workos_user_id
-- and email are deliberately fake — never commit a real identity. To drive the
-- UI in dev, point AUTH_BYPASS_USER_ID at this id (bypasses WorkOS), or override
-- workos_user_id locally to bind a real account outside source control.
on conflict (id) do nothing;

-- 2. Canonical exercises referenced by the program.
on conflict (id) do nothing;

-- 3. Program
on conflict (id) do nothing;

-- 4. Weeks 1-8
on conflict (id) do nothing;

-- 5. Days (same layout repeated for every week)
on conflict (id) do nothing;

-- 5b. Coach notes on a handful of week-1 days. These populate the read-only
-- "Coach" section of the side panel's Notes card. Newline-separated lines each
-- render as a bullet. Guarded with `notes is null` so re-running this seed never
-- clobbers a note edited in the running app; the rest of the days are left
-- without notes on purpose so the card's empty state stays reachable in dev.
update program_days set notes = E'Squat openers: belt + sleeves from set 2 onward.\nRIR work: stop 1 rep shy on the heaviest set.\nLog RPE on the last set of each block — it drives next week''s load cap.\nBar speed is the limiter; if you grind, cut the back-offs at 0.95.'
  where id = '78a3a15f-b735-4bf1-bdbc-ace8ac318e77' and notes is null;
update program_days set notes = E'Paused bench: full 2-count, no heave off the chest.\nKeep upper-back tight across the machine press back-offs.\nKelso shrugs: slow eccentric, squeeze the mid-traps.'
  where id = '9f113763-bf66-4840-94cf-5b54f150f6af' and notes is null;
update program_days set notes = E'Full rest day — stay non-sedentary.\n20–40 min easy walk; hydrate.\nHips + t-spine mobility, ~10 min.'
  where id = '66a2d597-3968-4816-90e0-a02b0d8430d7' and notes is null;

-- 6. Program exercises (one row per (week, day, contiguous exercise block))
on conflict (id) do nothing;

-- 7. Program set targets
on conflict (id) do nothing;

on conflict (id) do nothing;

-- 8. Sample sessions for week 1 with logged actuals (load + RPE) and every
--    set_log marked state='completed'. The auto-rollup rule requires the
--    session's parent state to match (sessions.state='completed' iff every
--    child set_log is completed-or-skipped); this seed satisfies that
--    invariant so the day-selector dots demo correctly and the workout
--    table shows fully-checked tri-state cells the user can still cycle.
--    by clicking, not something pre-applied.
--    Driven by the 'Load Used' and 'Last Set RPE' columns from sheet 1.
   started_at, completed_at, notes)
